/// Known-answer calibration consts.
///
/// These values describe one fixed synthetic plaintext we authored, NOT any
/// user save or game data. The compressed payload was generated by the live
/// host against the real game build and verified to round-trip back to that
/// plaintext. Oodle Kraken decode format is version-stable, so the compressed
/// bytes decode identically across builds, giving calibration a known-answer
/// decompress oracle that needs no user save. This plaintext is independent of
/// the separate `calibration_compress_input` buffer used for the compress test.
const CALIBRATION_SAMPLE_EXPECTED_SIZE: usize = 4096;
/// SHA-1 of the full decompressed synthetic plaintext.
const CALIBRATION_SAMPLE_DECOMPRESSED_SHA1: &str = "ac98ade89e3d7417584bc0aa8036a56d31d4e285";
/// Hex of the first 64 bytes of the decompressed synthetic plaintext.
const CALIBRATION_SAMPLE_DECOMPRESSED_HEAD_HEX: &str = "676f7265736176652d636f6465632d63616c6962726174696f6e2d73616d706c642c77302c454e2c4f4e552c524948512c46404c442c454055402c2c2c2c2c2c";
/// Base64 of the version-stable Oodle-compressed synthetic plaintext.
const CALIBRATION_SAMPLE_COMPRESSED_B64: &str = "";

/// The embedded known-answer decompress oracle for calibration.
pub fn calibration_sample() -> RuntimeSelftestOracleSample {
    RuntimeSelftestOracleSample {
        compressed_base64: CALIBRATION_SAMPLE_COMPRESSED_B64.to_string(),
        expected_size: CALIBRATION_SAMPLE_EXPECTED_SIZE,
        expected_decompressed_sha1: CALIBRATION_SAMPLE_DECOMPRESSED_SHA1.to_string(),
        expected_decompressed_head_hex: CALIBRATION_SAMPLE_DECOMPRESSED_HEAD_HEX.to_string(),
    }
}

/// Compression level used for the calibration compress selftest. Must match the
/// level the production write/roundtrip path uses (goresave_core compresses save
/// chunks at level 6) so a build is only reported write-capable when it works at
/// the level real saves will use.
const CALIBRATION_COMPRESS_LEVEL: u8 = 6;

/// A 4 KiB deterministic synthetic buffer used as the compress selftest input.
/// Independent of the decompress oracle: the worker compresses it then
/// decompresses the result to verify a real round-trip.
pub fn calibration_compress_input() -> Vec<u8> {
    (0..CALIBRATION_SAMPLE_EXPECTED_SIZE as u32)
        .map(|i| (i.wrapping_mul(73).wrapping_add(17) & 0xFF) as u8)
        .collect()
}

